"""Append the REG family rows R01-R15 to rosters/SOURCES.csv and update rows U21 and U22 (idempotent)."""
import csv, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
P = os.path.join(ROOT, 'SOURCES.csv')
rows = list(csv.reader(open(P, encoding='utf-8')))
hdr = rows[0]
rows = [r for r in rows if not (len(r) and r[0].startswith('R') and r[0][1:].isdigit() and int(r[0][1:]) <= 15)]


def setrow(i, **kw):
    for r in rows:
        if r[0] == i:
            for k, v in kw.items():
                r[hdr.index(k)] = v


setrow('U21', status='FETCHED', notes='REG family run 30 Oct 2026 (DEC-019): sources found and used, see rows R01-R15 and data/REG/README.md. Regular Army enlisted men and Delaware enlisted men remain unnamed (no open text source; the Delaware state volumes are handwritten image PDFs and no OCR engine is installed).')
